def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if r is not None and math.isfinite(r) and r > 0 and x > 0:
            total += x * r * r * r
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    nearest = [math.inf] * len(sites)
    for b in s.get('neighbors', ()):
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0:
            i = b['i']
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for i, site in enumerate(sites):
        w = site.get('occupancy', 1.0)
        if math.isfinite(nearest[i]) and w > 0:
            total += w * nearest[i]
            weight += w
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    nearest = [math.inf] * len(sites)
    for b in s.get('neighbors', ()):
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0:
            i = b['i']
            nearest[i] = min(nearest[i], d)
    weight = 0.0
    total = 0.0
    total2 = 0.0
    for i, site in enumerate(sites):
        w = site.get('occupancy', 1.0)
        d = nearest[i]
        if math.isfinite(d) and w > 0:
            weight += w
            total += w * d
            total2 += w * d * d
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return float(math.sqrt(max(0.0, total2 / weight - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', ())
    neighbors = s.get('neighbors', ())
    nearest = [math.inf] * len(sites)
    amounts = {}
    for site in sites:
        e = site.get('element')
        w = max(0.0, site.get('occupancy', 1.0))
        amounts[e] = amounts.get(e, 0.0) + w
    occupied = sum(amounts.values())
    if occupied <= 0:
        return 0.0
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0:
            i = b['i']
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    total = 0.0
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and 0 < d <= 1.25 * nearest[i]:
            w = max(0.0, sites[i].get('occupancy', 1.0)) * max(0.0, sites[j].get('occupancy', 1.0))
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    if total <= 0:
        return 0.0
    expected = 1.0 - sum((w / occupied) ** 2 for w in amounts.values())
    return float(unlike / total - expected)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        value = props.get(e, {}).get('valence_electrons')
        if value is not None and math.isfinite(value) and value >= 0 and x > 0:
            total += x * value
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0
